  8	/* LED Definitions for STM32F469I-DISCO (Active LOW) */
  9	/* LED1: PG6, LED2: PD4, LED3: PD5, LED4: PK3 */
 10	#define LED1_PIN              (6UL)
 11	#define LED2_PIN              (4UL)
 12	#define LED3_PIN              (5UL)
 13	#define LED4_PIN              (3UL)
 14	
 15	/* Button Definition (Active HIGH) - WAKEUP: PA0 */
 16	#define BUTTON_PIN            (0UL)
 17	
 18	/* Hàng đợi truyền tín hiệu sự kiện từ nút bấm PA0 sang tác vụ LED3 và LCD */
 19	static QueueHandle_t xButtonQueue = NULL;
 20	static QueueHandle_t xUIQueue = NULL;
 21	
 22	/* Cung cấp hàm thời gian HAL dựa trên FreeRTOS tick */
 23	uint32_t HAL_GetTick(void)
 24	{
 25	    if (xTaskGetSchedulerState() != taskSCHEDULER_NOT_STARTED) {
 26	        return (uint32_t)xTaskGetTickCount();
 27	    }
 28	    static volatile uint32_t fake_tick = 0;
 29	    return ++fake_tick;
 30	}
 31	
 32	void HAL_Delay(uint32_t Delay)
 33	{
 34	    if (xTaskGetSchedulerState() != taskSCHEDULER_NOT_STARTED) {
 35	        vTaskDelay(pdMS_TO_TICKS(Delay));
 36	    } else {
 37	        /* Vòng lặp chờ thô khi scheduler chưa khởi chạy */
 38	        for (volatile uint32_t i = 0; i < Delay * 4000; i++) {
 39	            __asm__("nop");
 40	        }
 41	    }
 42	}
 43	
 44	/* Khởi tạo ngoại vi phần cứng: 4 LED và nút WAKEUP PA0 */
 45	static void prvSetupHardware(void)
 46	{
 47	    /* Bật thạch anh ngoài HSE 8 MHz cấp nguồn clock cho DSI PLL và LTDC PLLSAI */
 48	    RCC->CR |= RCC_CR_HSEON;
 49	    for (volatile uint32_t timeout = 0; timeout < 100000; timeout++) {
 50	        if (RCC->CR & RCC_CR_HSERDY) {
 51	            break;
 52	        }
 53	    }
 54	
 55	    /* Đặt PLLM = 8 để HSE 8 MHz / 8 = 1 MHz cho đầu vào PLLSAI và main PLL */
 56	    RCC->PLLCFGR = (RCC->PLLCFGR & ~RCC_PLLCFGR_PLLM) | (8UL << RCC_PLLCFGR_PLLM_Pos);
 57	
 58	    /* Bật clock AHB1 cho GPIOA, GPIOD, GPIOG, GPIOK */
 59	    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOAEN | RCC_AHB1ENR_GPIODEN | RCC_AHB1ENR_GPIOGEN | RCC_AHB1ENR_GPIOKEN;
 60	
 61	    /* Cấu hình PA0 (Nút WAKEUP): Chế độ Input (00), Pull-down (10) */
 62	    GPIOA->MODER &= ~(3UL << (BUTTON_PIN * 2));
 63	    GPIOA->PUPDR &= ~(3UL << (BUTTON_PIN * 2));
 64	    GPIOA->PUPDR |= (2UL << (BUTTON_PIN * 2));
 65	
 66	    /* Cấu hình PG6 (LED1): Chế độ Output (01), tắt ban đầu (LED tích cực mức thấp) */
 67	    GPIOG->MODER &= ~(3UL << (LED1_PIN * 2));
 68	    GPIOG->MODER |= (1UL << (LED1_PIN * 2));
 69	    GPIOG->BSRR = (1UL << LED1_PIN);
 70	
 71	    /* Cấu hình PD4 (LED2) & PD5 (LED3): Chế độ Output (01), tắt ban đầu */
 72	    GPIOD->MODER &= ~((3UL << (LED2_PIN * 2)) | (3UL << (LED3_PIN * 2)));
 73	    GPIOD->MODER |= ((1UL << (LED2_PIN * 2)) | (1UL << (LED3_PIN * 2)));
 74	    GPIOD->BSRR = (1UL << LED2_PIN) | (1UL << LED3_PIN);
 75	
 76	    /* Cấu hình PK3 (LED4): Chế độ Output (01), tắt ban đầu */
 77	    GPIOK->MODER &= ~(3UL << (LED4_PIN * 2));
 78	    GPIOK->MODER |= (1UL << (LED4_PIN * 2));
 79	    GPIOK->BSRR = (1UL << LED4_PIN);
 80	}
