 82	/* Task 1: Nháy LED1 (PG6) theo chu kỳ 1000 ms (500 ms bật, 500 ms tắt) */
 83	static void vTaskLED1(void *pvParameters)
 84	{
 85	    (void)pvParameters;
 86	    for (;;) {
 87	        GPIOG->BSRR = (1UL << (LED1_PIN + 16)); /* Bật LED1 (mức thấp) */
 88	        vTaskDelay(pdMS_TO_TICKS(500));
 89	        GPIOG->BSRR = (1UL << LED1_PIN);        /* Tắt LED1 (mức cao) */
 90	        vTaskDelay(pdMS_TO_TICKS(500));
 91	    }
 92	}
 93	
 94	/* Task 2: Nháy LED2 (PD4) theo chu kỳ 400 ms (200 ms bật, 200 ms tắt) */
 95	static void vTaskLED2(void *pvParameters)
 96	{
 97	    (void)pvParameters;
 98	    for (;;) {
 99	        GPIOD->BSRR = (1UL << (LED2_PIN + 16)); /* Bật LED2 */
100	        vTaskDelay(pdMS_TO_TICKS(200));
101	        GPIOD->BSRR = (1UL << LED2_PIN);        /* Tắt LED2 */
102	        vTaskDelay(pdMS_TO_TICKS(200));
103	    }
104	}
